"""'What stands out': sentences generated by fixed rules from the numbers. They describe and never
advise. Each item is (bold lead, rest); templates escape both."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from robby.audit.measures import (
    OE_HIGH,
    OE_LOW,
    RATE_FLAG_POINTS,
    SIZE_FLAG_POINTS,
    UNCLASSIFIED_CALLOUT,
    Report,
)

Item = tuple[str, str]


@dataclass(frozen=True)
class FacilityComparison:
    """One national-overview line, as numbers."""

    name: str
    births: int
    ratio: Decimal | None
    unclassified_pct: Decimal | None


def _groups(numbers: list[int]) -> str:
    labels = [str(n) for n in numbers]
    if len(labels) == 1:
        return f"Group {labels[0]}"
    return "Groups " + ", ".join(labels[:-1]) + f" and {labels[-1]}"


def _verb(numbers: list[int], singular: str, plural: str) -> str:
    return singular if len(numbers) == 1 else plural


def facility_stands_out(report: Report) -> list[Item]:
    items: list[Item] = []
    if report.births == 0:
        return [("No births with a recorded outcome in this period.", "")]
    if report.reference is None:
        items.append(
            (
                "No reference set loaded.",
                " The figures below are this facility's own; nothing is compared.",
            )
        )
    else:
        both = [r.group for r in report.rows if r.larger_group and r.higher_rate and r.group]
        size_only = [
            r.group for r in report.rows if r.larger_group and not r.higher_rate and r.group
        ]
        rate_only = [
            r.group for r in report.rows if r.higher_rate and not r.larger_group and r.group
        ]
        if both:
            items.append(
                (
                    f"{_groups(both)} {_verb(both, 'is', 'are')} both larger than the reference "
                    "and "
                    f"{_verb(both, 'has a', 'have')} higher cesarean "
                    f"{_verb(both, 'rate', 'rates')}.",
                    " Together these make a group a large part of all cesareans.",
                )
            )
        if rate_only:
            items.append(
                (
                    f"{_groups(rate_only)} {_verb(rate_only, 'is not', 'are not')} larger than "
                    f"the reference, but the cesarean {_verb(rate_only, 'rate', 'rates')} "
                    f"{_verb(rate_only, 'is', 'are')} "
                    f"at least {RATE_FLAG_POINTS:.0f} points above it.",
                    " The difference lies in the rate within the group, not in the group's size.",
                )
            )
        if size_only:
            items.append(
                (
                    f"{_groups(size_only)} {_verb(size_only, 'is', 'are')} larger than the "
                    f"reference by at least {SIZE_FLAG_POINTS:.0f} points,",
                    f" but the cesarean {_verb(size_only, 'rate is', 'rates are')} less than "
                    f"{RATE_FLAG_POINTS:.0f} points above it.",
                )
            )
        if not (both or rate_only or size_only):
            items.append(
                (
                    "No group is flagged against the reference.",
                    f" Flags need a group size {SIZE_FLAG_POINTS:.0f} or more points above, or a "
                    f"rate {RATE_FLAG_POINTS:.0f} or more points above.",
                )
            )
    if report.unclassified_high:
        items.append(
            (
                f"{report.unclassified_pct}% of births could not be classified.",
                " Comparisons are less reliable until the missing or conflicting fields are "
                "completed.",
            )
        )
    if report.awaiting:
        items.append(
            (
                f"{report.awaiting} admissions in this period are awaiting an outcome.",
                " They are not in any rate above.",
            )
        )
    return items


def national_stands_out(rows: list[FacilityComparison], has_reference: bool) -> list[Item]:
    items: list[Item] = []
    if not has_reference:
        items.append(
            (
                "No reference set loaded.",
                " Expected rates cannot be computed; each facility's own figures are shown.",
            )
        )
    else:
        for r in rows:
            if r.ratio is None:
                continue
            gap = ((r.ratio - 1) * 100).copy_abs().quantize(Decimal(1))
            if r.ratio >= OE_HIGH:
                items.append(
                    (
                        f"{r.name}'s cesarean rate is {gap}% higher than expected for its case mix",
                        f" (observed ÷ expected {r.ratio}).",
                    )
                )
            elif r.ratio <= OE_LOW:
                items.append(
                    (
                        f"{r.name}'s cesarean rate is {gap}% lower than expected for its case mix",
                        f" (observed ÷ expected {r.ratio}).",
                    )
                )
        close = [r.name for r in rows if r.ratio is not None and OE_LOW < r.ratio < OE_HIGH]
        if close:
            items.append(
                (
                    f"{', '.join(close)} {'is' if len(close) == 1 else 'are'} within "
                    "10% of the rate expected for the case mix.",
                    "",
                )
            )
    high = [
        r.name for r in rows if r.unclassified_pct and r.unclassified_pct > UNCLASSIFIED_CALLOUT
    ]
    if high:
        items.append(
            (
                f"{', '.join(high)} could not classify more than {UNCLASSIFIED_CALLOUT:.0f}% of "
                "births,",
                " so comparisons for them are less reliable.",
            )
        )
    if not items:
        items.append(("No facility has births with a recorded outcome in this period.", ""))
    return items
